package com.example.starter.port;

/**
 * 携号转网流程状态。
 *
 * <p>流转：APPLIED（已申请）→ CODE_ISSUED（已签码）→ CONFIRMED（携出方已确认，待生效）
 * → EFFECTIVE（已生效，终态）；生效前可撤销进入 CANCELLED（终态）。
 */
public enum PortStatus {

    /** 已申请，资格校验通过，尚未签发授权码 */
    APPLIED,
    /** 授权码已签发，等待携出方确认 */
    CODE_ISSUED,
    /** 携出方已确认，等待生效窗口广播 */
    CONFIRMED,
    /** 已生效（终态） */
    EFFECTIVE,
    /** 已撤销（终态） */
    CANCELLED;

    /**
     * 判断是否为终态（已生效或已撤销）。
     */
    public boolean isTerminal() {
        return this == EFFECTIVE || this == CANCELLED;
    }
}

package com.example.starter.port;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态与稳定错误码，由全局异常处理器转换为响应体。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public BusinessException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    /**
     * 404：资源不存在。
     */
    public static BusinessException notFound(String code, String message) {
        return new BusinessException(HttpStatus.NOT_FOUND, code, message);
    }

    /**
     * 409：幂等冲突或状态冲突。
     */
    public static BusinessException conflict(String code, String message) {
        return new BusinessException(HttpStatus.CONFLICT, code, message);
    }

    /**
     * 422：业务规则不满足（资格、授权码、生效窗口等）。
     */
    public static BusinessException unprocessable(String code, String message) {
        return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }
}

package com.example.starter.port;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：统一使用 UTC 时钟，测试中可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 系统 UTC 时钟；授权码有效期与生效窗口均以此为准。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

